window.renderShopAdmin=async function({api,esc,money,date,busy,toast,testNotice,$,$$},host){
 host.innerHTML=`<div class="page-heading"><div><p class="eyebrow">Seqlyn Labs Shop</p><h1>Store administration</h1></div><a href="/shop-all-peptides/">View store</a></div>${testNotice}<nav class="admin-tabs" aria-label="Administration">${['overview','orders','products','discounts','requests','email','payments','settings'].map(k=>`<button class="secondary" data-tab="${k}" aria-pressed="false">${k[0].toUpperCase()+k.slice(1)}</button>`).join('')}</nav><section id="admin-content" aria-live="polite"></section>`;
 async function load(tab){$$('[data-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tab===tab)));const out=$('#admin-content');out.innerHTML='<p>Loading…</p>';try{await panel(tab,out);}catch(e){out.innerHTML=`<p class="error" role="alert">${esc(e.message)}</p><button id="retry-admin">Try again</button>`;$('#retry-admin').onclick=()=>load(tab);}}
 async function panel(tab,out){
 if(tab==='payments'){
  const config=await api('/api/admin/payments'),labels={crypto:'Crypto',apple_pay:'Apple Pay',paypal:'PayPal'};
  out.innerHTML=`<h2>Payment preferences</h2><p>Customers receive an order confirmation immediately. You receive their order and chosen payment method at the admin email; reply to send payment details after reviewing the order. Confirm the payment transaction before processing an order.</p><form id="payment-settings" class="narrow"><label class="check-label"><input type="checkbox" name="enabled" ${config.enabled?'checked':''}> Accept orders awaiting manual payment</label>${Object.entries(labels).map(([id,label])=>`<label class="check-label"><input type="checkbox" name="${id}" ${config.methods.find(m=>m.id===id)?.enabled?'checked':''}> ${label}</label>`).join('')}<button>Save payment preferences</button><p id="payment-settings-status" role="status"></p></form>`;
  $('#payment-settings').onsubmit=e=>{e.preventDefault();busy($('button',e.target),async()=>{const form=new FormData(e.target);await api('/api/admin/payments',{enabled:form.has('enabled'),methods:Object.keys(labels).map(id=>({id,enabled:form.has(id),instructions:''}))});$('#payment-settings-status').textContent='Payment preferences saved. Refresh checkout to see the change.';});};return;
 }
 if(tab==='email'){
  const r=await api('/api/admin/email'),counts=Object.fromEntries(r.counts.map(v=>[v.status,v.count])),subscribers=Object.fromEntries(r.subscribers.map(v=>[v.status,v.count]));
  out.innerHTML=`<h2>Email delivery</h2><p>${r.configured?'Email sending is configured.':'Email sending needs provider configuration.'} Messages marked accepted have been accepted by the email provider; check Resend for final delivery or bounce status.</p><p>${esc(counts.queued||0)} queued · ${esc(counts.accepted||0)} accepted · ${esc(counts.failed||0)} need attention · ${esc(subscribers.subscribed||0)} confirmed subscribers</p><button class="secondary" id="dispatch-email">Process queued messages</button><p id="email-status" role="status"></p><h3>Send a newsletter</h3><p>Only confirmed subscribers receive campaigns. Each message includes the business address and an unsubscribe link.</p>${r.newsletterReady?'':'<p class="error">Newsletter sending requires email configuration and the business mailing address.</p>'}<form id="newsletter-campaign" class="narrow"><label>Subject<input name="subject" required maxlength="150"></label><label>Message<textarea name="message" required rows="10" maxlength="10000"></textarea></label><button ${r.newsletterReady?'':'disabled'}>Send newsletter to ${esc(subscribers.subscribed||0)} subscribers</button><p id="campaign-status" role="status"></p></form><h3>Recent messages</h3><div class="table-scroll"><table><thead><tr><th>Type / recipient</th><th>Status</th><th>Attempts</th><th>Provider reference / issue</th></tr></thead><tbody>${r.messages.map(m=>`<tr><td>${esc(m.kind)}<br>${esc(m.recipient)}</td><td>${esc(m.status)}</td><td>${esc(m.attempts)}</td><td>${esc(m.error||m.provider_id||'—')}</td></tr>`).join('')}</tbody></table></div><h3>Recent campaigns</h3>${r.campaigns.map(c=>`<p>${esc(c.subject)} · ${esc(c.recipients)} recipients · ${esc(date(c.created_at))}</p>`).join('')||'<p>No campaigns yet.</p>'}`;
  async function drain(status){let accepted=0;for(let i=0;i<20;i++){const result=await api('/api/admin/email/dispatch',{});accepted+=result.accepted||0;status.textContent=accepted+' messages accepted by the provider. Refresh this tab to see current delivery status.';if(!result.configured||!result.processed)break;}}
  $('#dispatch-email').onclick=e=>busy(e.target,()=>drain($('#email-status')));
  let campaignId=crypto.randomUUID();
  $('#newsletter-campaign').onsubmit=e=>{e.preventDefault();if(!window.confirm('Send this newsletter to '+(subscribers.subscribed||0)+' confirmed subscribers?'))return;busy($('button',e.target),async()=>{const result=await api('/api/admin/newsletters',{id:campaignId,...Object.fromEntries(new FormData(e.target))});campaignId=crypto.randomUUID();$('#campaign-status').textContent=result.queued+' newsletter messages queued.';e.target.reset();await drain($('#campaign-status'));});};return;
 }
 if(tab==='overview'){const s=await api('/api/admin/overview');out.innerHTML=`<h2>Store overview</h2><div class="stat-grid">${[['Orders',s.orders],['Confirmed payments',money(s.paidValue||0)],['Pending orders',s.pending||0],['Products',s.products],['Low stock items',s.lowStock],['Customer requests',s.requests]].map(([l,n])=>`<article class="stat"><p>${l}</p><strong>${n}</strong></article>`).join('')}</div><p class="muted">Confirmed payments excludes unpaid, cancelled and historical test orders.</p>`;return;}
 if(tab==='orders'){
  out.innerHTML='<h2>Manage orders</h2><form id="order-filter" class="catalog-filters"><label>Search email or order ID<input name="q" type="search"></label><label>Status<select name="state"><option value="">All statuses</option>'+['pending','processing','shipped','delivered','cancelled'].map(s=>`<option>${s}</option>`).join('')+'</select></label><button>Search</button></form><div id="admin-orders"></div><div class="pagination" id="order-pages"></div>';let offset=0;
  async function render(){const f=new FormData($('#order-filter')),r=await api('/api/admin/orders?offset='+offset+'&state='+encodeURIComponent(f.get('state'))+'&q='+encodeURIComponent(f.get('q')));$('#admin-orders').innerHTML=r.orders.length?r.orders.map(o=>`<details class="admin-order" data-order="${esc(o.id)}"><summary><strong>${esc(o.id.slice(0,8).toUpperCase())}</strong> ${esc(o.email)} <span class="badge">${esc(o.status==='test'?'Historical test':o.status==='paid'?'Paid':'Awaiting payment')} - ${esc(o.fulfillment)}</span> ${money(o.total)}</summary><p>${esc(date(o.created_at))}${o.payment?' - Payment method: '+esc(o.payment.label):''}</p>${o.status==='awaiting_payment'&&o.fulfillment!=='cancelled'?`<form class="payment-confirmation"><input type="hidden" name="id" value="${esc(o.id)}"><label>Payment transaction reference<input name="reference" required maxlength="500"></label><button>Confirm payment received</button><p>Confirm only after checking the payment in your wallet or payment provider.</p></form>`:''}<div class="columns"><section><h3>Items</h3>${JSON.parse(o.items).map(i=>`<p>${esc(i.name)} × ${i.quantity} · ${money(i.price*i.quantity)}</p>`).join('')}<h3>Shipping address</h3><pre>${esc(Object.values(JSON.parse(o.shipping)).join('\n'))}</pre></section><form class="order-editor"><input type="hidden" name="id" value="${esc(o.id)}"><label>Fulfillment status<select name="fulfillment">${['pending','processing','shipped','delivered','cancelled'].map(s=>`<option ${o.fulfillment===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Carrier<input name="carrier" maxlength="200" value="${esc(o.carrier)}"></label><label>Tracking reference<input name="tracking" maxlength="200" value="${esc(o.tracking)}"></label><label>Internal notes<textarea name="notes" maxlength="2000">${esc(o.notes)}</textarea></label><button>Save order</button><p role="status" class="order-message"></p></form></div><button class="secondary" data-history="${esc(o.id)}">View change history</button><div class="order-history"></div></details>`).join(''):'<p>No orders match these filters.</p>';$('.payment-confirmation').forEach(form=>form.onsubmit=e=>{e.preventDefault();busy($('button',form),async()=>{await api('/api/admin/orders/payment',Object.fromEntries(new FormData(form)));await render();toast('Payment confirmed. The order can now be processed.');});});$('.order-editor').forEach(form=>form.onsubmit=e=>{e.preventDefault();busy($('button',form),async()=>{await api('/api/admin/orders',Object.fromEntries(new FormData(form)));$('.order-message',form).textContent='Order saved.';$('.badge',form.closest('details')).textContent=$('[name=fulfillment]',form).value;});});$$('[data-history]').forEach(btn=>btn.onclick=()=>busy(btn,async()=>{const r=await api('/api/admin/events?id='+encodeURIComponent(btn.dataset.history));$('.order-history',btn.closest('details')).innerHTML=r.events.map(e=>`<p>${esc(date(e.created_at))} · ${esc(e.action)}</p><pre>${esc(e.data)}</pre>`).join('')||'<p>No recorded changes.</p>';}));$('#order-pages').innerHTML=`<button id="order-prev" ${offset===0?'disabled':''}>Previous</button><span>Page ${Math.floor(offset/50)+1}</span><button id="order-next" ${r.next===null?'disabled':''}>Next</button>`;$('#order-prev').onclick=()=>{offset=Math.max(0,offset-50);render().catch(e=>toast(e.message));};$('#order-next').onclick=()=>{offset=r.next;render().catch(e=>toast(e.message));};}
  $('#order-filter').onsubmit=e=>{e.preventDefault();offset=0;render().catch(e=>toast(e.message));};await render();return;
 }
 if(tab==='products'){
  const r=await api('/api/admin/products');out.innerHTML='<h2>Products & inventory</h2><p>Manage parent products and each size separately. Blank stock means the quantity is unknown. Submitted orders reserve known stock; cancelling an unpaid order restores it. Historical test orders do not deduct stock.</p><label>Find a product<input id="admin-product-search" type="search" placeholder="Product name or SKU"></label><div class="table-scroll"><table><thead><tr><th>Product / SKU</th><th>Price (USD)</th><th>Stock</th><th>Active</th><th></th></tr></thead><tbody>'+r.products.map(p=>`<tr data-product="${esc(p.id)}"><td>${p.parentId?'↳ ':''}<strong>${esc(p.name)}</strong><small>${esc(p.id)}${p.variable?' · parent product':''}</small></td><td><input aria-label="Price for ${esc(p.name)}" name="price" type="number" step="0.01" min="0" value="${p.price/100}"></td><td><input aria-label="Stock for ${esc(p.name)}" name="stock" type="number" min="0" step="1" value="${p.stock??''}"></td><td><input aria-label="Active ${esc(p.name)}" name="active" type="checkbox" ${p.active?'checked':''}></td><td><button>Save</button>${p.custom?`<button class="secondary" data-edit-product="${esc(p.id)}">Edit details</button>`:''}</td></tr>`).join('')+'</tbody></table></div>';
  const editor=document.createElement('section');editor.innerHTML='<h3 id="product-editor-title">Add a product</h3><form id="catalog-editor" class="narrow"><label>SKU / URL slug<input name="id" required pattern="[a-z0-9][a-z0-9-]{2,79}" maxlength="80" placeholder="new-research-product"></label><label>Product name<input name="name" required maxlength="200"></label><label>Description<textarea name="description" rows="4" maxlength="3000"></textarea></label><label>Image URL (HTTPS)<input name="image" type="url" required placeholder="https://..."></label><label>Category<select name="category"><option value="vials">Vials</option><option value="capsules">Capsules</option><option value="sprays">Sprays</option><option value="serums">Serums</option><option value="oral-sprays">Oral sprays</option><option value="uncategorized">Other</option></select></label><label>Price (USD)<input name="price" type="number" min="0" step="0.01" required></label><label>Stock (blank = unknown)<input name="stock" type="number" min="0" step="1"></label><div class="actions"><button>Save product</button><button type="button" class="secondary" id="reset-catalog-editor">New product</button></div><p id="catalog-editor-message" role="status"></p></form>';out.append(editor);
  const productForm=$('#catalog-editor');productForm.onsubmit=e=>{e.preventDefault();busy($('button',productForm),async()=>{const f=Object.fromEntries(new FormData(productForm));if(!productForm.elements.id.readOnly&&r.products.some(p=>p.id===f.id)){toast('That SKU already exists. Choose a new SKU.');return;}await api('/api/admin/catalog',{...f,price:Math.round(Number(f.price)*100),stock:f.stock===''?null:Number(f.stock)});await panel(tab,out);toast('Product saved.');});};
  $('#reset-catalog-editor').onclick=()=>{productForm.reset();productForm.elements.id.readOnly=false;$('#product-editor-title').textContent='Add a product';};
  $$('[data-edit-product]').forEach(btn=>btn.onclick=()=>{const p=r.products.find(p=>p.id===btn.dataset.editProduct);for(const key of ['id','name','description','image'])productForm.elements[key].value=p[key]||'';productForm.elements.category.value=p.categories[0];productForm.elements.price.value=p.price/100;productForm.elements.stock.value=p.stock??'';productForm.elements.id.readOnly=true;$('#product-editor-title').textContent='Edit '+p.name;editor.scrollIntoView({behavior:'smooth'});});
  $('#admin-product-search').oninput=e=>$$('[data-product]').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(e.target.value.toLowerCase()));
  $$('[data-product]').forEach(row=>$('button',row).onclick=e=>busy(e.target,async()=>{await api('/api/admin/products',{id:row.dataset.product,price:Math.round(Number($('[name=price]',row).value)*100),stock:$('[name=stock]',row).value===''?null:Number($('[name=stock]',row).value),active:$('[name=active]',row).checked?1:0});toast('Product saved.');}));return;
 }
 if(tab==='discounts'){
  const r=await api('/api/admin/coupons');out.innerHTML=`<h2>Discount codes</h2><div class="table-scroll"><table><thead><tr><th>Code</th><th>Discount</th><th>Minimum</th><th>Uses / limit</th><th>Expiry</th><th>Status</th><th></th></tr></thead><tbody>${r.coupons.map(c=>`<tr><td>${esc(c.code)}</td><td>${c.kind==='percent'?c.amount+'%':money(c.amount)}</td><td>${money(c.minimum)}</td><td>${c.uses} / ${c.max_uses||'unlimited'}</td><td>${c.expires?esc(date(c.expires)):'No expiry'}</td><td>${c.active?'Active':'Disabled'}</td><td><button class="secondary" data-coupon="${esc(c.code)}">${c.active?'Disable':'Enable'}</button></td></tr>`).join('')||'<tr><td colspan="7">No discount codes yet.</td></tr>'}</tbody></table></div><h3>Create a code</h3><form id="new-coupon" class="narrow"><label>Code<input name="code" required pattern="[A-Za-z0-9_-]{3,30}" maxlength="30"></label><label>Discount type<select name="kind"><option value="percent">Percentage</option><option value="fixed">Fixed amount (USD)</option></select></label><label>Amount<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Minimum spend (USD)<input name="minimum" type="number" min="0" step="0.01" value="0" required></label><label>Maximum uses (0 = unlimited)<input name="max_uses" type="number" min="0" step="1" value="0" required></label><label>Expires at (your local time)<input name="expires" type="datetime-local"></label><button>Create code</button><p role="alert" class="error" id="coupon-admin-error"></p></form><p class="muted">Existing code terms are fixed. Disable a code and create a new one to change its terms.</p>`;
  $$('[data-coupon]').forEach(btn=>btn.onclick=()=>busy(btn,async()=>{const c=r.coupons.find(c=>c.code===btn.dataset.coupon);await api('/api/admin/coupons',{...c,active:c.active?0:1});await panel(tab,out);}));
  const amount=$('[name=amount]',$('#new-coupon'));amount.step='1';amount.min='1';amount.max='100';$('[name=kind]',$('#new-coupon')).onchange=e=>{amount.step=e.target.value==='percent'?'1':'0.01';amount.min=e.target.value==='percent'?'1':'0.01';amount.max=e.target.value==='percent'?'100':'100000';};
  $('#new-coupon').onsubmit=e=>{e.preventDefault();busy($('button',e.target),async()=>{const f=Object.fromEntries(new FormData(e.target));if(r.coupons.some(c=>c.code===f.code.trim().toUpperCase())){$('#coupon-admin-error').textContent='That code already exists. Choose a new code.';return;}await api('/api/admin/coupons',{...f,amount:f.kind==='percent'?Number(f.amount):Math.round(Number(f.amount)*100),minimum:Math.round(Number(f.minimum)*100),max_uses:Number(f.max_uses),expires:f.expires?new Date(f.expires).toISOString():'',active:1});await panel(tab,out);toast('Discount code created.');});};return;
 }
 if(tab==='requests'){const r=await api('/api/admin/submissions');out.innerHTML=`<h2>Customer requests</h2>${r.submissions.map(s=>{const d=JSON.parse(s.data);return `<details class="admin-order"><summary><strong>${esc(s.kind)}</strong> ${esc(d.email)} · ${esc(date(s.created_at))}</summary><p>${esc(d.message||'Newsletter signup')}</p></details>`;}).join('')||'<p>No requests yet.</p>'}<p class="muted">Requests remain saved here. The Email tab shows queued notifications and provider acceptance.</p>`;return;}
 if(tab==='settings'){const s=await api('/api/admin/settings');out.innerHTML=`<h2>Checkout settings</h2><p>Configure the shipping charge, free shipping threshold and tax rate for U.S. deliveries.</p><form id="store-settings" class="narrow"><label>Flat shipping (USD)<input name="shipping" type="number" min="0" step="0.01" value="${s.shipping/100}" required></label><label>Free shipping minimum (USD, 0 = disabled)<input name="freeShipping" type="number" min="0" step="0.01" value="${s.freeShipping/100}" required></label><label>Tax rate (%)<input name="tax" type="number" min="0" max="100" step="0.01" value="${s.taxBasisPoints/100}" required></label><button>Save settings</button><p id="settings-message" role="status"></p></form><h3>Store configuration</h3><dl><dt>Checkout mode</dt><dd>See Payment preferences</dd><dt>Currency</dt><dd>USD</dd><dt>Payment provider</dt><dd>Manual payment after order review</dd><dt>Commerce backend</dt><dd>Independent store</dd></dl>`;$('#store-settings').onsubmit=e=>{e.preventDefault();busy($('button',e.target),async()=>{const f=Object.fromEntries(new FormData(e.target));await api('/api/admin/settings',{shipping:Math.round(Number(f.shipping)*100),freeShipping:Math.round(Number(f.freeShipping)*100),taxBasisPoints:Math.round(Number(f.tax)*100)});$('#settings-message').textContent='Checkout settings saved.';});};}
 }
 $$('[data-tab]').forEach(b=>b.onclick=()=>load(b.dataset.tab));await load('overview');
};
